namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious pizza with fresh mozzarella, tomatoes, and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = [
                "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                "Stretch dough into a 12-inch round on a floured surface.",
                "Spread crushed tomatoes evenly over the dough.",
                "Tear mozzarella into pieces and distribute over the sauce.",
                "Bake for 10–12 minutes until crust is golden and cheese is bubbly.",
                "Top with fresh basil leaves and a drizzle of olive oil."
            ],
            TotalRatings = 12, RatingSum = 52
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
            Steps = [
                "Marinate chicken in yogurt, garam masala, and salt for at least 1 hour.",
                "Grill or broil chicken until charred and cooked through.",
                "Sauté onion, garlic, and ginger in oil until softened.",
                "Add spices and cook for 1 minute until fragrant.",
                "Add tomato sauce and simmer for 15 minutes.",
                "Stir in cream, add chicken pieces, and simmer 10 more minutes."
            ],
            TotalRatings = 8, RatingSum = 36
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in crispy taco shells with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = [
                "Brown ground beef in a skillet over medium-high heat.",
                "Add taco seasoning and water, simmer until thickened.",
                "Warm taco shells in the oven for 3 minutes.",
                "Fill shells with seasoned beef.",
                "Top with lettuce, tomato, cheese, sour cream, and salsa."
            ],
            TotalRatings = 15, RatingSum = 60
        },
        new()
        {
            Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Classic Roman pasta with eggs, pecorino cheese, guanciale, and black pepper.",
            Ingredients = ["Spaghetti", "Guanciale or pancetta", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
            Steps = [
                "Cook spaghetti in salted boiling water until al dente.",
                "Crisp guanciale in a skillet until golden.",
                "Whisk eggs with grated pecorino and plenty of black pepper.",
                "Drain pasta, reserving some cooking water.",
                "Toss hot pasta with guanciale, then remove from heat.",
                "Quickly stir in egg mixture, adding pasta water to create a creamy sauce."
            ],
            TotalRatings = 10, RatingSum = 45
        },
        new()
        {
            Id = 5, Title = "Pad Thai", Category = "Asian",
            Description = "Stir-fried rice noodles with shrimp, tofu, peanuts, and tamarind sauce.",
            Ingredients = ["Rice noodles", "Shrimp", "Firm tofu", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Sugar", "Lime"],
            Steps = [
                "Soak rice noodles in warm water for 30 minutes, then drain.",
                "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                "Stir-fry tofu until golden, then add shrimp and cook through.",
                "Push to the side, scramble eggs in the pan.",
                "Add noodles and sauce, toss everything together.",
                "Serve topped with peanuts, bean sprouts, green onions, and lime wedges."
            ],
            TotalRatings = 6, RatingSum = 25
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh and creamy avocado dip with lime and cilantro.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt", "Garlic"],
            Steps = [
                "Halve and pit avocados, scoop flesh into a bowl.",
                "Mash with a fork to desired consistency.",
                "Stir in diced onion, tomato, jalapeño, and minced garlic.",
                "Add lime juice, chopped cilantro, and salt to taste.",
                "Serve immediately with tortilla chips."
            ],
            TotalRatings = 20, RatingSum = 88
        },
        new()
        {
            Id = 7, Title = "Butter Chicken", Category = "Indian",
            Description = "Rich and creamy tomato-based curry with tender chicken.",
            Ingredients = ["Chicken thighs", "Butter", "Tomato purée", "Heavy cream", "Garam masala", "Kashmiri chili powder", "Garlic", "Ginger", "Fenugreek leaves"],
            Steps = [
                "Marinate chicken in yogurt and spices for 2 hours.",
                "Grill or pan-fry chicken until cooked through.",
                "Melt butter, sauté garlic and ginger until fragrant.",
                "Add tomato purée, chili powder, and simmer 20 minutes.",
                "Stir in cream and fenugreek leaves.",
                "Add chicken and simmer 10 minutes. Serve with naan or rice."
            ],
            TotalRatings = 14, RatingSum = 63
        },
        new()
        {
            Id = 8, Title = "Teriyaki Salmon", Category = "Asian",
            Description = "Glazed salmon fillets with a sweet and savory teriyaki sauce.",
            Ingredients = ["Salmon fillets", "Soy sauce", "Mirin", "Brown sugar", "Garlic", "Ginger", "Sesame seeds", "Green onions"],
            Steps = [
                "Mix soy sauce, mirin, brown sugar, garlic, and ginger for the glaze.",
                "Pat salmon dry and season with salt and pepper.",
                "Sear salmon skin-side up in a hot skillet for 3 minutes.",
                "Flip and pour glaze over the salmon.",
                "Cook 4–5 more minutes, spooning glaze over the fish.",
                "Garnish with sesame seeds and sliced green onions."
            ],
            TotalRatings = 9, RatingSum = 40
        },
    ];

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted {submission.Category.ToLowerInvariant()} recipe.",
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
        });
    }
}

