arguments.file_text:
@rendermode InteractiveServer

<div class="star-rating d-inline-flex align-items-center gap-1">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button type="button"
                class="btn btn-link p-0 fs-4 text-decoration-none @(star <= DisplayRating ? "text-warning" : "text-secondary")"
                @onclick="() => Rate(star)"
                title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= DisplayRating ? "★" : "☆")
        </button>
    }
    <span class="ms-2 text-muted small">
        (@TotalRatings rating@(TotalRatings != 1 ? "s" : ""), avg @AverageRating.ToString("F1"))
    </span>
</div>

@code {
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int TotalRatings { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int? _userRating;
    private int DisplayRating => _userRating ?? (int)Math.Round(AverageRating);

    private async Task Rate(int stars)
    {
        _userRating = stars;
        await OnRated.InvokeAsync(stars);
    }
}

@page "/"
@using RecipeShare.Services

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-4">
    <h1 class="display-4">🍳 RecipeShare</h1>
    <p class="lead text-muted">Discover and share delicious recipes from around the world.</p>
</div>

<h2 class="mb-3">Browse by Category</h2>

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4">
    @foreach (var category in Categories)
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title fs-4">@GetEmoji(category) @category</h3>
                    <p class="card-text text-muted">
                        @RecipeService.GetByCategory(category).Count recipe@(RecipeService.GetByCategory(category).Count != 1 ? "s" : "")
                    </p>
                    <a href="category/@category" class="btn btn-outline-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="text-center mt-5">
    <h4>Have a recipe to share?</h4>
    <a href="submit" class="btn btn-success btn-lg mt-2">Submit a Recipe</a>
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private static string GetEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Asian" => "🥢",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"
@using RecipeShare.Services
@using RecipeShare.Models

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var recipe in Recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <div class="mb-2">
                            <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                            <small class="text-muted ms-1">(@recipe.TotalRatings)</small>
                        </div>
                    </div>
                    <div class="card-footer bg-transparent">
                        <a href="recipe/@recipe.Id" class="btn btn-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<div class="mt-4">
    <a href="/" class="btn btn-outline-secondary">← Back to Categories</a>
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<Recipe> Recipes = [];

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="category/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active" aria-current="page">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <p class="lead text-muted">@Recipe.Description</p>

    <StarRating AverageRating="@Recipe.AverageRating"
                TotalRatings="@Recipe.TotalRatings"
                OnRated="HandleRating" />

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <h4>Instructions</h4>
            <ol class="list-group list-group-numbered list-group-flush">
                @foreach (var step in Recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
